def sha256_file(filepath):
    """Compute SHA256 hash using sha256sum command."""
    try:
        resolved = os.path.realpath(filepath)
        result = subprocess.run(['sha256sum', resolved], capture_output=True, text=True, timeout=10)
        if result.returncode == 0:
            return result.stdout.split()[0]
    except Exception:
        pass
    return None

def is_suspicious_cron_line(line, is_system_cron=True):
    """Check if a cron line is suspicious."""
    stripped = line.strip()
    # Skip empty lines and comments
    if not stripped or stripped.startswith('#'):
        return False
    # Skip variable assignments (like SHELL=/bin/sh)
    if re.match(r'^[A-Za-z_][A-Za-z0-9_]*=', stripped):
        return False

    # Check for temp directories
    if re.search(r'(?:^|[\s;|&])/(?:tmp|var/tmp)[/ ]', stripped) or '/tmp/' in stripped or '/var/tmp' in stripped:
        return True

    # Check for obfuscated commands
    if re.search(r'\b(?:base64|eval)\b', stripped):
        return True
    if re.search(r'\b(?:wget|curl)\s', stripped):
        return True

    # Extract command portion
    parts = stripped.split()
    if len(parts) < 6:
        return False

    # Determine command start index
    cmd_start = 5
    if is_system_cron and len(parts) > 5:
        # Check if 6th field looks like a username
        candidate = parts[5]
        if not candidate.startswith('/') and not candidate.startswith('-') and not candidate.startswith('$'):
            # Likely a username
            cmd_start = 6

    if cmd_start >= len(parts):
        return False

    cmd = parts[cmd_start]

    # Check if command is an absolute path outside standard locations
    if cmd.startswith('/'):
        standard_prefixes = ['/usr/bin/', '/bin/', '/sbin/', '/usr/sbin/', '/usr/bin', '/bin', '/sbin', '/usr/sbin']
        if not any(cmd.startswith(p) for p in standard_prefixes):
            return True

    # Check for unusual timing patterns
    time_fields = stripped.split()[:5]
    if len(time_fields) == 5:
        # Every minute
        if time_fields == ['*', '*', '*', '*', '*']:
            return True
        # Random intervals like */5
        if any(t.startswith('*/') for t in time_fields):
            return True

    return False

def is_suspicious_systemd_unit(filepath):
    """Check if a systemd unit file is suspicious."""
    try:
        basename = os.path.basename(filepath)
        # Hidden files are suspicious
