            return True

        content = ""
        with open(filepath, 'r', errors='replace') as f:
            content = f.read()

        # Check for suspicious ExecStart commands
        for line in content.splitlines():
            line = line.strip()
            if line.startswith('ExecStart'):
                # Check for temp directories
                if '/tmp/' in line or '/var/tmp' in line:
                    return True
                # Check for obfuscated commands
                if re.search(r'\b(?:base64|eval)\b', line):
                    return True
                if re.search(r'\b(?:wget|curl)\s', line):
                    return True
                # Check for suspicious commands
                if re.search(r'\b(?:nc|ncat|netcat)\b', line):
                    return True
                # Check for scripts outside standard paths
                exec_match = re.search(r'ExecStart=([^#\n]*)', line)
                if exec_match:
                    exec_cmd = exec_match.group(1).strip()
                    # Extract the actual executable
                    cmd_parts = exec_cmd.split()
                    if cmd_parts:
                        cmd = cmd_parts[0]
                        if cmd.startswith('/'):
                            standard_prefixes = ['/usr/bin/', '/bin/', '/sbin/', '/usr/sbin/', '/usr/bin', '/bin', '/sbin', '/usr/sbin']
                            if not any(cmd.startswith(p) for p in standard_prefixes):
                                return True
        return False
    except Exception:
        return False

def has_rclocal_suspicious_lines(filepath):
    """Find suspicious lines in rc.local file."""
    suspicious_lines = []
    try:
        with open(filepath, 'r', errors='replace') as f:
            lines = f.readlines()
    except Exception:
        return suspicious_lines

    for i, line in enumerate(lines, 1):
        stripped = line.strip()
        # Skip empty lines
        if not stripped:
            continue
        # Skip comments
        if stripped.startswith('#'):
            continue
        # Skip shebang
        if stripped.startswith('#!'):
            continue
        # Skip standard exit command
        if re.match(r'^exit\b', stripped):
            continue
        # Any other non-empty, non-comment line is suspicious
        suspicious_lines.append((i, stripped))

    return suspicious_lines

def is_ssh_key_line(line):
    """Check if a line is an SSH public key."""
    stripped = line.strip()
    if not stripped or stripped.startswith('#'):
        return False
    key_patterns = ['ssh-rsa', 'ssh-ed25519', 'ssh-dss', 'ecdsa-sha2-', 'sk-ssh-ed25519', 'sk-ecdsa-sha2']
    return any(stripped.startswith(p) for p in key_patterns)

def extract_username_from_path(filepath):
    """Extract username from authorized_keys path."""
    # /home/username/.ssh/authorized_keys -> username
    # /root/.ssh/authorized_keys -> root
    # /app_target/home/username/.ssh/authorized_keys -> username
    # /app_target/root/.ssh/authorized_keys -> root
    parts = filepath.split('/')
    if len(parts) >= 5:
        # Check for /home/username/ pattern
        for i, p in enumerate(parts):
            if p == 'home' and i + 1 < len(parts):
                return parts[i + 1]
        # Check for /root/ pattern
        for i, p in enumerate(parts):
            if p == 'root' and i + 1 < len(parts) and parts[i + 1] == '.ssh':
                return 'root'
    return None

def collect_files(base, relative_paths):
    """Collect files from base + relative paths."""
    files = []
    for rel in relative_paths:
        full = os.path.join(base, rel) if base != '/' else '/' + rel.lstrip('/')
        if os.path.isfile(full) or os.path.islink(full):
            files.append(full)
    return files

